<script setup>
import {computed} from 'vue';
const props=defineProps({state:{type:Object,default:()=>({})},version:{type:String,default:'0.5.9'},links:{type:Object,default:()=>({})},view:String,compact:Boolean});
defineEmits(['diagnostics']);
const status=computed(()=>props.state.status||{});
const errors=computed(()=>Object.entries(status.value.streamErrors||{}));
const hardError=computed(()=>['error','dependency-error'].includes(status.value.mode));
const warning=computed(()=>Boolean(status.value.lastError)||errors.value.length>0);
const label=computed(()=>{const s=status.value;if(s.connected)return s.mode==='demo'?'DEMO':hardError.value?'LIVE · ERROR':errors.value.length?'LIVE · DATA ERROR':warning.value?'LIVE · WARNING':'LIVE';return s.stale?'STALE':s.mode==='live'?'OFFLINE':s.mode==='demo'?'DEMO · NO DATA':String(s.mode||'CONNECTING').toUpperCase()});
const detail=computed(()=>{const s=status.value;const name=s.directorName||s.directorHost||s.seedHost||'—';const host=s.directorIp&&s.directorIp!==name?`${name} - ${s.directorIp}`:name;return s.stale?`${host} · data not updating · PRESS D`:errors.value.length?`${host} · ${errors.value.length} stream error(s) · ${errors.value[0][0]}: ${errors.value[0][1]?.message||String(errors.value[0][1]||'property error')} · PRESS D`:s.lastError?`${host} · ${s.lastError}`:s.mode?`${host} · ${s.scheduleItems??0} mapped media items`:'Connecting to Designer…'});
</script>
<template><footer :class="{footer:!compact}"><button id="status-button" class="status-button" type="button" title="Open diagnostics (D)" @click="$emit('diagnostics')"><span id="status-dot" class="status-dot" :class="{connected:status.connected,error:hardError||warning}"></span><span id="status-text">{{label}}</span></button><span id="status-detail" class="status-detail" role="status" :title="detail">{{detail}}</span><nav class="footer-links" aria-label="Dashboard views and tools"><span id="footer-version">v{{String(version).replace(/^v/,'')}}</span><span v-if="!compact" class="footer-separator" aria-hidden="true">·</span><template v-for="(name,index) in (compact?[]:['advanced','simple'])" :key="name"><span v-if="index" class="footer-separator" aria-hidden="true">/</span><a :id="'view-'+name" class="view-link" :class="{'is-current':view===name}" :aria-current="view===name?'page':undefined" :href="links[name]||name+'.html'">{{name.toUpperCase()}}</a></template><span class="footer-separator" aria-hidden="true">·</span><a id="diagnostics-link" class="footer-link" href="diagnostics.html" aria-haspopup="dialog" title="Open diagnostics (D)" @click.prevent="$emit('diagnostics')">DIAGNOSTICS <small v-if="compact">D</small><kbd v-else class="footer-key">D</kbd></a><span class="footer-separator" aria-hidden="true">·</span><span v-if="compact" class="author-link">viavision.pro</span><a v-else class="author-link" href="https://viavision.pro" target="_blank" rel="noopener noreferrer">viavision.pro</a></nav></footer></template>
